import textwrap

from duration import MIN_MAIN_SECONDS, duration_frame_bounds, main_scene_count, resolve_duration

ALLOW_REPEATED_NARRATION = True
# CELL 3 — Detailed user prompt → AI brief → structured story
# Gemma 2 2B runs inside this runtime through Ollama; no cloud inference or API key.
# A T4 GPU is recommended. CPU execution also works, more slowly.
KINDS = ["hook", "workflow", "documents", "escalation", "cta"]
AI_CACHE = PROJECT_DIR / "ai_cache"
AI_CACHE.mkdir(exist_ok=True)


def object_schema(properties):
    return dict(
        type="object",
        properties=properties,
        required=list(properties),
        additionalProperties=False,
    )


STR = {"type": "string"}
STR_LIST = {"type": "array", "items": STR}
SEGMENT_SCHEMA = object_schema(
    {"text": STR, "delivery": {"type": "string", "enum": list(DELIVERY)}}
)
SEGMENTS_SCHEMA = {"type": "array", "items": SEGMENT_SCHEMA, "minItems": 1, "maxItems": 6}
SCENE_SCHEMA = object_schema(
    {
        "kind": {"type": "string", "enum": KINDS},
        "heading": STR,
        "subtitle": STR,
        "items": {"type": "array", "items": STR, "minItems": 1, "maxItems": 4},
        "callout": STR,
        "visual_query": STR,
        "top_right_header": STR,
        "segments": SEGMENTS_SCHEMA,
    }
)
BRIEF_SCHEMA = object_schema(
    {
        "duration_seconds": {"type": "number", "minimum": 1, "maximum": 86400},
        "audience": STR,
        "tone": STR,
        "goal": STR,
        "must_cover": STR_LIST,
        "assumptions": STR_LIST,
        "duration_was_explicit": {"type": "boolean"},
    }
)
STORY_SCHEMA = object_schema(
    {
        "title": STR,
        "brief": BRIEF_SCHEMA,
        "scenes": {"type": "array", "items": SCENE_SCHEMA, "minItems": 1, "maxItems": 40},
    }
