SYSTEM = """You write substantive, accurate, English-language explainer videos for narration by Brian.
Follow the user's topic, audience, tone, examples and call to action. Treat reference notes as source material.
Never invent legal deadlines, eligibility rules, statistics, URLs, quotations, or sources. Do not claim to
have browsed. If a critical fact is absent, use qualified language or identify it as something to verify.
Use the available runtime for useful explanations and concrete examples; avoid repetitive filler.
Return exactly the requested JSON schema. English narration is required for the configured en-US voice.
On-screen headings <=45 characters, subtitle <=85 characters, items <=38 characters, callout <=60 characters.
Use a short headline and 1–2 concise items whenever possible. Narration carries the detail.
Avoid repeating the heading in the subtitle or repeating the subtitle in the callout.
Scene kinds are visual layout choices: workflow=steps/process, documents=checklist/facts,
escalation=progression/challenges, hook=introduction, cta=closing action. They can cover ANY topic.
Segments are complete sentences or short clauses with natural punctuation, no SSML, Markdown, stage
instructions or emotion labels inside spoken text. Select delivery per segment; emphasis should be sparse.
Prefer 2–4 segments per scene, connected enough to sound natural. Do not read the prompt aloud."""


def shorten_display(text, limit=120):
    text = " ".join(str(text).split())
    if len(text) <= limit:
        return text
    shortened = textwrap.shorten(text, width=limit, placeholder="…")
    return shortened if shortened != "…" else text[: limit - 1] + "…"


# Normalize model-written delivery labels before schema validation or synthesis.
DELIVERY_ALIASES = {
    "emphatic": "emphasis",
    "emphasized": "emphasis",
    "emphasised": "emphasis",
    "emphasize": "emphasis",
    "emphasise": "emphasis",
    "emphatically": "emphasis",
    "assertive": "emphasis",
    "confident": "emphasis",
    "empathetic": "empathetic",
    "empathic": "empathetic",
    "sympathetic": "empathetic",
    "warm": "empathetic",
    "gentle": "empathetic",
    "compassionate": "empathetic",
    "cheerful": "upbeat",
    "enthusiastic": "upbeat",
    "excited": "upbeat",
    "energetic": "upbeat",
    "solemn": "serious",
    "somber": "serious",
    "sombre": "serious",
    "formal": "serious",
    "normal": "neutral",
    "calm": "neutral",
    "default": "neutral",
    "narration": "neutral",
}


def normalize_delivery_labels(data):
    # Handles complete stories, individual scenes, AND segments-only timing revisions.
    # Only metadata is changed; every segment's spoken text is preserved.
    if isinstance(data, dict):
        segments = data.get("segments")
        if isinstance(segments, list):
            for segment in segments:
                if not isinstance(segment, dict):
                    continue
                original = segment.get("delivery")
                key = original.strip().casefold() if isinstance(original, str) else ""
                canonical = DELIVERY_ALIASES.get(key, key)
                if canonical not in DELIVERY:
                    warnings.warn(f"Unsupported delivery {original!r}; using neutral.")
                    canonical = "neutral"
                segment["delivery"] = canonical
        for key, value in data.items():
            if key != "segments":
                normalize_delivery_labels(value)
    elif isinstance(data, list):
        for item in data:
            normalize_delivery_labels(item)
    return data


def repair_scene_lists(data):
    # Normalize display-only fields and voice metadata; preserve every spoken word.
    if not isinstance(data, dict):
        return data
    normalize_delivery_labels(data)
    if isinstance(data.get("title"), str):
        data["title"] = shorten_display(data["title"], 80) or "Video overview"
    is_scene = any(key in data for key in ("heading", "items", "callout"))
    candidates = data.get("scenes", [data] if is_scene else [])
    if isinstance(candidates, list):
        for scene in candidates:
            if not isinstance(scene, dict):
                continue
            items = scene.get("items", [])
            items = (
                [shorten_display(x, 120) for x in items if isinstance(x, str) and x.strip()][:4]
                if isinstance(items, list)
                else []
            )
            heading = scene.get("heading")
            heading = heading.strip() if isinstance(heading, str) else ""
            # Reuse existing scene copy rather than inventing a factual claim.
            label = heading or (items[0] if items else "Scene overview")
            scene["heading"] = shorten_display(label, 45)
            scene["top_right_header"] = shorten_display(scene.get("top_right_header") or label, 240)
            scene["items"] = items or [shorten_display(label, 120)]
            for key, limit in [("subtitle", 85), ("callout", 60), ("visual_query", 100)]:
                text = scene.get(key)
                if not isinstance(text, str) or not text.strip():
                    text = scene["items"][0] if key == "callout" else label
                scene[key] = shorten_display(text, limit)
    return data


def strip_unexpected_fields(data, schema):
    # Drop only unknown keys explicitly forbidden by this schema.
    # Required fields, type checks, enum checks and word-budget checks still apply.
    if isinstance(data, dict) and schema.get("type") == "object":
        properties = schema.get("properties", {})
        if schema.get("additionalProperties") is False:
            for key in list(data):
                if key not in properties:
                    del data[key]
        for key, value in data.items():
            if key in properties:
                strip_unexpected_fields(value, properties[key])
    elif isinstance(data, list) and schema.get("type") == "array":
        for item in data:
            strip_unexpected_fields(item, schema.get("items", {}))
    return data


# Local model lifecycle: install once, start once, download once, reuse between scenes.
# Only loopback requests are used for inference. Cloud models are rejected.
OLLAMA_URL = "http://127.0.0.1:11434"
_OLLAMA_READY_FOR = None
_OLLAMA_SESSION = requests.Session()
_OLLAMA_SESSION.trust_env = False  # Never route local prompts through an HTTP proxy.


def ollama_is_running():
    """Check the local process without downloading or loading a model."""
    try:
        response = _OLLAMA_SESSION.get(OLLAMA_URL + "/api/version", timeout=2)
        return response.ok
    except requests.RequestException:
        return False


def check_ollama_binary(path):
    """Reject missing, non-executable or incomplete installations before starting them."""
    if not path or not Path(path).is_file():
        return False
    try:
        result = subprocess.run([str(path), "--version"], capture_output=True, timeout=20)
        return result.returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


def download_ollama_archive(url, archive):
    """Download the official bundle with bounded retries and resumable partial files."""
    if archive.is_file():
        return
    partial = archive.with_suffix(archive.suffix + ".partial")
    for attempt in range(1, 4):
        offset = partial.stat().st_size if partial.exists() else 0
        headers = {"Range": f"bytes={offset}-"} if offset else {}
        try:
            with requests.get(url, headers=headers, stream=True, timeout=(15, 90)) as response:
                if response.status_code == 416:
                    if offset and response.headers.get("Content-Range") == f"bytes */{offset}":
                        partial.replace(archive)
                        return
                    partial.unlink(missing_ok=True)
                    raise ValueError("The partial download expired; restarting it.")
                response.raise_for_status()
                if response.status_code == 206:
                    prefix = f"bytes {offset}-"
                    if not response.headers.get("Content-Range", "").startswith(prefix):
                        partial.unlink(missing_ok=True)
                        raise ValueError("The download resumed at an unexpected offset.")
                else:
                    offset = 0  # The server ignored Range: safely start the file again.
                expected = int(response.headers.get("Content-Length", 0))
                written, last_progress = 0, 0
                with partial.open("ab" if offset else "wb") as output:
                    for chunk in response.iter_content(1024 * 1024):
                        if not chunk:
                            continue
                        output.write(chunk)
                        written += len(chunk)
                        if written - last_progress >= 128 * 1024 * 1024:
                            print(f"  Runtime downloaded: {(offset+written)/1024**2:.0f} MB")
                            last_progress = written
                if expected and written != expected:
                    raise ValueError("The runtime download was incomplete.")
            partial.replace(archive)
            return
        except (requests.RequestException, ValueError) as exc:
            if attempt == 3:
                raise RuntimeError(f"Runtime download failed after 3 attempts: {exc}") from exc
            print(f"  Download interrupted; retrying ({attempt+1}/3)...")


def install_portable_ollama():
    """Extract the official bundle in this project: no apt, sudo, useradd or systemd."""
    import platform
    import tarfile
    import importlib

    try:
        zstandard = importlib.import_module("zstandard")
    except ImportError:
        print("Installing the Python archive reader...")
        result = subprocess.run(
            [sys.executable, "-m", "pip", "install", "-q", "zstandard>=0.23,<1"],
            capture_output=True,
            text=True,
            timeout=180,
        )
        if result.returncode:
            raise RuntimeError("Cannot install zstandard:\n" + result.stderr[-2000:])
        importlib.invalidate_caches()
        zstandard = importlib.import_module("zstandard")
    architecture = {"x86_64": "amd64", "aarch64": "arm64", "arm64": "arm64"}.get(
        platform.machine()
    )
    if not sys.platform.startswith("linux") or not architecture:
        raise RuntimeError(
            "This automatic setup supports Linux. Install Ollama manually on this system."
        )
    runtime_dir = Path(os.environ.get("VIDEO_SHARED_ROOT", str(PROJECT_DIR))) / "runtime"
    runtime_dir.mkdir(parents=True, exist_ok=True)
    archive = runtime_dir / f"ollama-linux-{architecture}.tar.zst"
    destination = runtime_dir / "ollama"
    staging = runtime_dir / "ollama.installing"
    log_path = DEBUG_DIR / "ollama_install.log"
    url = f"https://ollama.com/download/ollama-linux-{architecture}.tar.zst"
    print("Installing Ollama in the project folder. First run only...")
    try:
        download_ollama_archive(url, archive)
        if staging.exists():
            shutil.rmtree(staging)
        staging.mkdir()
        print("Extracting the runtime with Python...")
        if not hasattr(tarfile, "data_filter"):
            raise RuntimeError(
                "Archive safety support is missing. Use a current Colab Python runtime."
            )
        with archive.open("rb") as compressed:
            with zstandard.ZstdDecompressor().stream_reader(compressed) as stream:
                with tarfile.open(fileobj=stream, mode="r|") as bundle:
                    bundle.extractall(staging, filter="data")
        executable = staging / "bin" / "ollama"
        if executable.exists():
            executable.chmod(executable.stat().st_mode | 0o111)
        if not check_ollama_binary(executable):
            raise RuntimeError("The extracted Ollama executable cannot run in this runtime.")
        if destination.exists():
            # Preserve an incomplete old installation for debugging instead of overwriting it.
            backup = runtime_dir / f"ollama.previous.{time.time_ns()}"
            destination.rename(backup)
        staging.rename(destination)
        executable = destination / "bin" / "ollama"
        log_path.write_text(
            f"Portable installation succeeded.\nExecutable: {executable}\n", encoding="utf-8"
        )
        archive.unlink(missing_ok=True)  # The extracted runtime is reused on later runs.
        return str(executable)
    except Exception as exc:
        log_path.write_text(
            f"Portable installation failed: {type(exc).__name__}: {exc}\n", encoding="utf-8"
        )
        if isinstance(exc, (tarfile.TarError, zstandard.ZstdError, EOFError)):
            archive.unlink(missing_ok=True)  # Never reuse a corrupt bundle on the next attempt.
        raise RuntimeError(f"Ollama setup failed: {exc}\nDetails: {log_path}") from exc


def ensure_ollama():
    """Start a verified executable directly and report the real startup error inline."""
    if ollama_is_running():
        return
    portable = Path(os.environ.get("VIDEO_SHARED_ROOT", str(PROJECT_DIR))) / "runtime" / "ollama" / "bin" / "ollama"
    candidates = [portable, shutil.which("ollama"), "/usr/local/bin/ollama", "/usr/bin/ollama"]
    executable = next((str(path) for path in candidates if check_ollama_binary(path)), None)
    if executable is None:
        executable = install_portable_ollama()
    environment = os.environ.copy()
    environment.update(
        OLLAMA_HOST="127.0.0.1:11434",
        OLLAMA_NO_CLOUD="1",
        OLLAMA_MAX_LOADED_MODELS="1",
        OLLAMA_NUM_PARALLEL="1",
        OLLAMA_CONTEXT_LENGTH=str(MODEL_CONTEXT_TOKENS),
    )
    log_path = DEBUG_DIR / "ollama_server.log"
    with log_path.open("w") as log:
        process = subprocess.Popen(
            [executable, "serve"],
            env=environment,
            stdout=log,
            stderr=log,
            start_new_session=True,
        )
    for _ in range(60):
        if ollama_is_running():
            print("Ollama is running locally.")
            return
        if process.poll() is not None:
            break
        time.sleep(1)
    detail = log_path.read_text(encoding="utf-8", errors="replace")[-2000:]
    raise RuntimeError(f"Ollama did not start.\n{detail}\nFull log: {log_path}")


def load_local_model():
    """Download Gemma 2 2B if absent; generation loads it automatically."""
    global _OLLAMA_READY_FOR
    if ":cloud" in MODEL_ID or "/" in MODEL_ID or "http" in MODEL_ID:
        raise ValueError(
            "Use a local Ollama model tag such as gemma2:2b. Cloud inference is disabled."
        )
    if _OLLAMA_READY_FOR == MODEL_ID and ollama_is_running():
        return
    ensure_ollama()
    response = _OLLAMA_SESSION.get(OLLAMA_URL + "/api/tags", timeout=15)
    response.raise_for_status()
    installed = {model["name"] for model in response.json().get("models", [])}
    if MODEL_ID not in installed:
        print(f"Downloading {MODEL_ID}. First run only; keep this cell running...")
        last_status, last_percent = "", -25
        with _OLLAMA_SESSION.post(
            OLLAMA_URL + "/api/pull",
            json={"model": MODEL_ID, "stream": True},
            stream=True,
            timeout=(10, 900),
        ) as response:
            response.raise_for_status()
            for line in response.iter_lines():
                if not line:
                    continue
                event = json.loads(line)
                if event.get("error"):
                    raise RuntimeError(f"Gemma download failed: {event['error']}")
                status = event.get("status", "")
                total = event.get("total", 0)
                percent = int(100 * event.get("completed", 0) / total) if total else None
                if status != last_status:
                    print("  " + status)
                    last_status, last_percent = status, -25
                if percent is not None and percent >= last_percent + 25:
                    print(f"  {percent}%")
                    last_percent = percent
    _OLLAMA_READY_FOR = MODEL_ID
    print(f"Local model ready: {MODEL_ID}.")


def unload_local_model():
    """Free model memory after narration rewrites; keep the runtime available for reruns."""
    global _OLLAMA_READY_FOR
    if _OLLAMA_READY_FOR is None:
        return
    try:
        response = _OLLAMA_SESSION.post(
            OLLAMA_URL + "/api/generate", json={"model": MODEL_ID, "keep_alive": 0}, timeout=30
        )
        response.raise_for_status()
    except requests.RequestException as exc:
        warnings.warn(f"Could not confirm model unload: {exc}")
    _OLLAMA_READY_FOR = None


def generate_local_json(instruction, schema):
    """Constrain generation with a JSON schema, then independently validate in Python."""
    if len(SYSTEM) + len(instruction) > MAX_PROMPT_CHARACTERS:
        raise ValueError("The brief exceeds the local context budget. Shorten REFERENCE_NOTES.")
    response = _OLLAMA_SESSION.post(
        OLLAMA_URL + "/api/generate",
        json={
            "model": MODEL_ID,
            "system": SYSTEM,
            "prompt": instruction,
            "format": schema,
            "stream": False,
            "keep_alive": "10m",
            "options": {
                "temperature": 0,
                "seed": 42,
                "num_ctx": MODEL_CONTEXT_TOKENS,
                "num_predict": MODEL_OUTPUT_TOKENS,
            },
        },
        timeout=(10, 600),
    )
    response.raise_for_status()
    result = response.json()
    save_json(DEBUG_DIR / "model_last_response.json", result)
    if result.get("error"):
        raise RuntimeError(result["error"])
    if result.get("done_reason") == "length":
        raise ValueError(
            "Model output reached its token limit. Shorten the scene or reference notes; see debug/model_last_response.json."
        )
    return result.get("response", "")


def ai_json(task, schema, name="video_story", cache=True):
    """One readable route for cached generation, normalization, validation and retries."""
    digest = hashlib.sha256(
        json.dumps(
            [MODEL_ID, SYSTEM, task, schema, MODEL_CONTEXT_TOKENS, MODEL_OUTPUT_TOKENS],
            sort_keys=True,
            ensure_ascii=False,
        ).encode()
    ).hexdigest()
    cached = AI_CACHE / f"{digest}.json"

    def validate_output(data):
        data = strip_unexpected_fields(repair_scene_lists(data), schema)
        validate_json(data, schema)
        return data

    if cache and cached.exists():
        try:
            return validate_output(json.loads(cached.read_text(encoding="utf-8")))
        except (ValueError, ValidationError):
            pass
    load_local_model()
    instruction = task + "\nReturn only JSON that matches this schema:\n" + json.dumps(schema)
    debug_name = re.sub(r"[^\w.-]", "_", name)
    for attempt in range(1, 4):
        save_json(DEBUG_DIR / f"{debug_name}_request.json", {"task": task, "schema": schema})
        try:
            raw = generate_local_json(instruction, schema)
        except requests.RequestException as exc:
            raise RuntimeError(
                f"Local model request failed during {name}. Rerun Cell 3; check debug/ollama_server.log."
            ) from exc
        (DEBUG_DIR / f"{debug_name}_attempt_{attempt}.txt").write_text(raw, encoding="utf-8")
        try:
            start = raw.find("{")
            if start < 0:
                raise ValueError("Gemma returned no JSON object.")
            data, _ = json.JSONDecoder().raw_decode(raw[start:])
            data = validate_output(data)
            if cache:
                save_json(cached, data)
            return data
        except (ValueError, ValidationError) as exc:
            if attempt == 3:
                raise RuntimeError(
                    f"Gemma could not finish {name} after 3 attempts. "
                    f"Last response rejected: {str(exc).splitlines()[0][:240]}"
                ) from exc
            print(f"  Repairing {name}: attempt {attempt+1}/3")
            instruction = (
                task
                + "\nCorrect this JSON. Return the requested schema only.\n"
                + raw[-6000:]
                + "\nProblem: "
                + str(exc)[:600]
            )


def word_count(segments):
    return len(re.findall(r"\b[\w’'-]+\b", " ".join(s["text"] for s in segments)))


def spoken_key(text):
    return " ".join(re.findall(r"[\w’'-]+", text.casefold()))


def repeated_narration(segments, previous_scenes=()):
    """Find substantial repeated sentences or almost identical scene scripts."""
    if ALLOW_REPEATED_NARRATION:
        return []
    seen = set()
    prior_scripts = []
    for scene in previous_scenes:
        script = " ".join(s["text"] for s in scene["segments"])
        prior_scripts.append(spoken_key(script).split())
        for segment in scene["segments"]:
            for sentence in re.split(r"(?<=[.!?])\s+", segment["text"].strip()):
                key = spoken_key(sentence)
                if len(key.split()) >= 6:
                    seen.add(key)
    repeated = []
    for segment in segments:
        for sentence in re.split(r"(?<=[.!?])\s+", segment["text"].strip()):
            key = spoken_key(sentence)
            if len(key.split()) >= 6:
                if key in seen:
                    repeated.append(sentence)
                seen.add(key)
    words = spoken_key(" ".join(s["text"] for s in segments)).split()
    grams = {tuple(words[i : i + 5]) for i in range(len(words) - 4)}
    for prior in prior_scripts:
        old = {tuple(prior[i : i + 5]) for i in range(len(prior) - 4)}
        if len(words) >= 12 and len(prior) >= 12 and grams and old:
            if len(grams & old) / min(len(grams), len(old)) >= 0.85:
                repeated.append("This scene substantially repeats an earlier scene.")
                break
    return repeated


def remove_repeated_sentences(segments, previous_scenes):
    """Keep unique complete sentences; never shorten one halfway or invent new copy."""
    if ALLOW_REPEATED_NARRATION:
        return json.loads(json.dumps(segments))
    result = []
    for segment in segments:
        for sentence in re.split(r"(?<=[.!?])\s+", segment["text"].strip()):
            candidate = {"text": sentence.strip(), "delivery": segment["delivery"]}
            if not candidate["text"]:
                continue
            earlier = [*previous_scenes, {"segments": result}]
            if not repeated_narration([candidate], earlier):
                result.append(candidate)
    # Preserve the public maximum segment count after splitting multi-sentence text.
    while len(result) > 6:
        result[-2]["text"] += " " + result[-1]["text"]
        result.pop()
    return result


def scene_source_material(topic, scene_index, previous_scenes):
    """Select source text for this scene instead of asking a small model to reread the script."""
    # Explicit Scene 1 / Slide 1 blocks take priority when the user supplied them.
    pattern = r"(?im)^\s*(?:\*\*)?(?:scene|slide)\s+(\d+)\b[^\n]*"
    markers = list(re.finditer(pattern, VIDEO_PROMPT))
    chosen_block = ""
    for index, marker in enumerate(markers):
        if int(marker[1]) == scene_index + 1:
            end = markers[index + 1].start() if index + 1 < len(markers) else len(VIDEO_PROMPT)
            chosen_block = VIDEO_PROMPT[marker.start() : end]
            break
    source = chosen_block or "\n".join(
        [VIDEO_PROMPT, REFERENCE_NOTES, *BRIEF.get("must_cover", [])]
    )
    sentences = [x.strip() for x in re.split(r"(?<=[.!?])\s+|\n+", source) if x.strip()]
    # Earlier spoken sentences are not useful positive examples for a new scene.
    candidates = []
    seen = set()
    for position, sentence in enumerate(sentences):
        key = spoken_key(sentence)
        if key in seen or repeated_narration(
            [{"text": sentence, "delivery": "neutral"}], previous_scenes
        ):
            continue
        seen.add(key)
        candidates.append((position, sentence))
    ignored = {
        "the",
        "and",
        "with",
        "your",
        "this",
        "that",
        "for",
        "from",
        "into",
        "scene",
        "slide",
    }
    topic_words = set(spoken_key(topic).split()) - ignored
    ranked = sorted(
        candidates,
        key=lambda item: (-len(topic_words & set(spoken_key(item[1]).split())), item[0]),
    )
    selected = sorted(ranked[:6], key=lambda item: item[0])
    # Preserve whole sentences in order; very long prompts remain bounded.
    material = []
    for _, sentence in selected:
        if sum(map(len, material)) + len(sentence) <= 3000:
            material.append(sentence)
    return "\n".join(material) or topic


def scene_kind_options(task):
    required = task["required_kind"]
    return (
        [required] if required in ("hook", "cta") else ["workflow", "documents", "escalation"]
    )


def clean_scene_candidate(candidate, task, previous_scenes):
    """Apply display normalization and reject repeated narration before accepting a scene."""
    scene = repair_scene_lists(json.loads(json.dumps(candidate)))
    scene = {key: scene[key] for key in SCENE_SCHEMA["properties"]}
    allowed = scene_kind_options(task)
    if scene["kind"] not in allowed:
        scene["kind"] = allowed[0]
    original = [segment for segment in scene["segments"] if segment["text"].strip()]
    cleaned = remove_repeated_sentences(original, previous_scenes)
    if not cleaned or word_count(cleaned) < 5:
        raise ValueError("The scene needs at least five usable narration words.")
    if cleaned != original:
        # A few residual words are not a complete replacement for a copied scene.
        if word_count(cleaned) < min(8, max(5, round(task["word_budget"] * 0.35))):
            raise ValueError("Too little new narration remains; write this scene again.")
    scene["segments"] = cleaned
    validate_json(scene, SCENE_SCHEMA)
    for key, limit in [
        ("heading", 45),
        ("subtitle", 85),
        ("callout", 60),
        ("visual_query", 100),
    ]:
        if not scene[key].strip() or len(scene[key]) > limit:
            raise ValueError(f"{key} must contain 1–{limit} characters.")
    repeats = repeated_narration(scene["segments"], previous_scenes)
    if repeats:
        raise ValueError("The proposed narration substantially repeats an earlier scene.")
    return scene


def scene_repair_request(task, previous_scenes, attempt, narration_only):
    """Give Gemma the current topic and its relevant source text."""
    is_opening = task["scene_number"] == 1
    focus = [
        (
            "Introduce this topic once, with a concise hook."
            if is_opening
            else "Explain this scene's specific point. Continue after the introduction."
        ),
        "Describe this scene's source-supported cause or consequence, using fresh wording.",
        "State this scene's practical takeaway and explain it with the supplied material.",
    ][min(attempt - 1, 2)]
    instructions = [
        "Write ONLY the CURRENT scene, not the whole video.",
        focus,
        (
            "Return a narration string with two concise spoken sentences and at least five words."
            if narration_only
            else "Return a complete scene JSON with 1–2 short display items and 1–3 narration segments."
        ),
        (
            "This is the opening scene. Introduce the topic once."
            if is_opening
            else "Do not write the introduction again."
        ),
        "Do not invent facts or repeat earlier topics.",
        "Use the source as reference material. Write complete sentences without placeholders.",
    ]
    if globals().get("END_CARD"):
        instructions.append(
            "A fixed closing card is added separately. Do not narrate or recreate its message."
        )
    return {
        "task": " ".join(instructions),
        "current_scene": {
            "number": task["scene_number"],
            "topic": task["topic"],
            "allowed_layouts": scene_kind_options(task),
        },
        "source_material": scene_source_material(
            task["topic"], task["scene_number"] - 1, previous_scenes
        ),
        "audience": BRIEF.get("audience", ""),
        "tone": BRIEF.get("tone", ""),
        "goal": BRIEF.get("goal", ""),
        "already_covered_topics": task["outline"][: task["scene_number"] - 1],
        "target_word_count": task["word_budget"],
        "closing_card_added_separately": bool(globals().get("END_CARD")),
        "attempt": attempt,
    }


def scene_from_narration(text, task):
    """Build only display fields locally, using the approved topic and spoken copy."""
    heading = shorten_display(task["topic"], 45)
    sentences = re.split(r"(?<=[.!?])\s+", text.strip())
    return {
        "kind": scene_kind_options(task)[0],
        "heading": heading,
        "subtitle": shorten_display(sentences[0], 85),
        "items": [shorten_display(sentence, 120) for sentence in (sentences[1:3] or sentences[:1])],
        "callout": shorten_display(sentences[-1], 60),
        "visual_query": shorten_display(task["topic"], 100),
        "top_right_header": shorten_display(task["topic"], 240),
        "segments": [{"text": text.strip(), "delivery": "neutral"}],
    }


def write_distinct_scene(task, previous_scenes, title):
    """Reuse accepted scenes; repair only the failed scene without disabling validation."""
    approved_dir = AI_CACHE / "approved_scenes"
    approved_dir.mkdir(exist_ok=True)
    digest = hashlib.sha256(
        json.dumps(
            ["distinct-v1", MODEL_ID, SYSTEM, task, SCENE_SCHEMA],
            sort_keys=True,
            ensure_ascii=False,
        ).encode()
    ).hexdigest()
    approved = approved_dir / f"{digest}.json"
    if approved.exists():
        try:
            return clean_scene_candidate(
                json.loads(approved.read_text(encoding="utf-8")), task, previous_scenes
            )
        except (ValueError, KeyError, ValidationError):
            approved.unlink(missing_ok=True)
    attempts = []
    last_candidate = None
    for attempt in range(1, 5):
        narration_only = attempt >= 3
        mode = "narration_only" if narration_only else "full_scene"
        if attempt == 1:
            # Keep the old request/schema so valid cached scenes remain reusable.
            request, schema = task, SCENE_SCHEMA
        else:
            request = scene_repair_request(task, previous_scenes, attempt - 1, narration_only)
            if narration_only:
                schema = object_schema({"narration": STR})
            else:
                schema = json.loads(json.dumps(SCENE_SCHEMA))
                schema["properties"]["kind"]["enum"] = scene_kind_options(task)
                schema["properties"]["segments"]["maxItems"] = 3
        try:
            response = ai_json(
                json.dumps(request, ensure_ascii=False),
                schema,
                f"scene_{task['scene_number']}_{mode}_{attempt}",
                cache=attempt == 1,
            )
            last_candidate = (
                scene_from_narration(response["narration"], task) if narration_only else response
            )
            scene = clean_scene_candidate(last_candidate, task, previous_scenes)
            save_json(approved, scene)
            if narration_only:
                print(f"Scene {task['scene_number']}: recovered with a narration-only draft.")
            if attempt > 1 or scene["segments"] != last_candidate["segments"]:
                attempts.append(
                    {
                        "attempt": attempt,
                        "mode": mode,
                        "status": "accepted",
                    }
                )
                SCENE_REPAIR_LOG.append(
                    {
                        "scene": task["scene_number"],
                        "topic": task["topic"],
                        "attempts": attempts,
                    }
                )
                save_json(OUTPUT_DIR / "scene_repair_log.json", SCENE_REPAIR_LOG)
            return scene
        except (ValueError, KeyError, ValidationError, RuntimeError) as exc:
            if isinstance(exc, RuntimeError) and not str(exc).startswith(
                "Gemma could not finish"
            ):
                raise  # Connectivity/setup failures need their original actionable error.
            message = str(exc)
            reason = message.splitlines()[0][:400] if message else type(exc).__name__
            attempts.append(
                {"attempt": attempt, "mode": mode, "status": "rejected", "reason": reason}
            )
            print(f"Scene {task['scene_number']}, {mode} attempt {attempt} rejected: {reason}")
    SCENE_REPAIR_LOG.append(
        {"scene": task["scene_number"], "topic": task["topic"], "attempts": attempts}
    )
    save_json(OUTPUT_DIR / "scene_repair_log.json", SCENE_REPAIR_LOG)
    save_json(
        OUTPUT_DIR / "story_repair_draft.json",
        {
            "title": title,
            "brief": BRIEF,
            "scenes": previous_scenes,
            "failed_scene_number": task["scene_number"],
            "failed_scene_topic": task["topic"],
            "rejected_candidate": last_candidate,
        },
    )
    raise RuntimeError(
        f"Scene {task['scene_number']} ({task['topic']}) could not produce usable narration. "
        f"Last rejection: {attempts[-1]['reason']} Check scene_repair_log in the job report."
    )


def frame_plan(target, count):
    total = round(target * FPS)
    transition = max(1, round(TRANSITION_SECONDS * FPS))
    targets = [scene.get("_target_seconds") for scene in globals().get("STORY", {}).get("scenes", [])]
    if len(targets) == count and all(value is not None for value in targets):
        quotas = [total * value / sum(targets) for value in targets]
        frames = [math.floor(quota) for quota in quotas]
        remaining = total - sum(frames)
        for index in sorted(range(count), key=lambda i: quotas[i] - frames[i], reverse=True)[:remaining]:
            frames[index] += 1
        return total, transition, [
            value + (transition if index < count - 1 else 0)
            for index, value in enumerate(frames)
        ]
    q, rem = divmod(total + (count - 1) * transition, count)
    return total, transition, [q + (i < rem) for i in range(count)]


def validate_story(story):
    # Persisted story contains extra runtime metadata; validate the core projection only.
    core = {k: story[k] for k in ("title", "brief")}
    core["scenes"] = [{k: s[k] for k in SCENE_SCHEMA["properties"]} for s in story["scenes"]]
    validate_json(core, STORY_SCHEMA)
    if not story["title"].strip() or len(story["title"]) > 80:
        raise ValueError("Keep the story title within 80 characters.")
    if story["scenes"][0]["kind"] != "hook" or (len(story["scenes"]) > 1 and story["scenes"][-1]["kind"] != "cta"):
        raise ValueError("The first scene must use hook and the last scene must use cta.")
    for scene in story["scenes"]:
        for key, limit in [
            ("heading", 45),
            ("subtitle", 85),
            ("callout", 60),
            ("visual_query", 100),
        ]:
            if not scene[key].strip() or len(scene[key]) > limit:
                raise ValueError(f"{key} must contain 1–{limit} characters: {scene[key]}")
        scene["items"] = [shorten_display(x, 120) if isinstance(x, str) and x.strip() else "Key insight" for x in scene.get("items", ["Key insight"])]
        if any(not x["text"].strip() for x in scene["segments"]):
            raise ValueError("Narration segments cannot be empty.")
    return story


