# Geometry uses a 1920x1080 design canvas and scales to preview resolution.
from functools import lru_cache

SCALE = WIDTH / 1920


def find_font(custom, bold=False):
    if custom:
        if not Path(custom).is_file():
            raise FileNotFoundError(custom)
        return str(custom)
    names = (
        ["DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf"]
        if bold
        else ["DejaVuSans.ttf", "LiberationSans-Regular.ttf"]
    )
    for root in (
        Path("/usr/share/fonts/truetype"),
        Path("/usr/local/share/fonts"),
        Path("C:/Windows/Fonts"),
    ):
        if root.exists():
            for name in names:
                match = next(root.rglob(name), None)
                if match:
                    return str(match)
    # Pillow can also resolve fonts installed on the runtime's font search path.
    for name in names:
        try:
            return ImageFont.truetype(name, 24).path
        except OSError:
            pass
    raise RuntimeError("No suitable TrueType font. Set FONT_REGULAR and FONT_BOLD in Cell 2.")


REGULAR_PATH, BOLD_PATH = find_font(FONT_REGULAR), find_font(FONT_BOLD or FONT_REGULAR, True)


@lru_cache(maxsize=128)
def font(size, bold=False):
    return ImageFont.truetype(BOLD_PATH if bold else REGULAR_PATH, max(1, round(size * SCALE)))


def wrap_pixels(text, f, width):
    lines = []
    for paragraph in text.split("\n"):
        line = ""
        for word in paragraph.split():
            candidate = (line + " " + word).strip()
            if f.getlength(candidate) <= width:
                line = candidate
            else:
                if line:
                    lines.append(line)
                line = ""
                for char in word:
                    if line and f.getlength(line + char) > width:
                        lines.append(line)
                        line = ""
                    line += char
        lines.append(line)
    return lines


@lru_cache(maxsize=512)
def fit_text(text, width, height, size, minimum, bold):
    width *= SCALE
    height *= SCALE
    for n in range(size, minimum - 1, -1):
        f = font(n, bold)
        lines = wrap_pixels(text, f, width)
        leading = math.ceil(f.size * 1.35)
        if leading * len(lines) <= height and all(
            f.getlength(line) <= width for line in lines
        ):
            return f, lines, leading

    # Keep all spoken copy and fit only the display text to its reserved space.
    max_lines = int(height // leading)
    if max_lines < 1 or f.getlength("…") > width:
        return f, [], leading
    visible = lines[:max_lines]
    last = visible[-1].rstrip()
    while last and f.getlength(last + "…") > width:
        last = last[:-1].rstrip()
    visible[-1] = last + "…"
    return f, visible, leading


def text_box(draw, text, box, size=64, minimum=24, bold=False, fill=None):
    x, y, _, _ = box
    f, lines, leading = fit_text(text, box[2], box[3], size, minimum, bold)
    for j, line in enumerate(lines):
        draw.text(
            (round(x * SCALE), round(y * SCALE) + j * leading),
            line,
            font=f,
            fill=fill or DESIGN["ink"],
            anchor="lt",
        )


